ExpressionFunction.Expression:
Math.If(


	prop_DynamicLabelText == List.list_DynamicLabelText.BatteryFuelLevel,

	Math.If(


obj_BatteryElectricTruck.tbl_TruckTypes[
obj_BatteryElectricTruck.tbl_TruckTypes.TruckType.RowForKey(
String.FromList(obj_BatteryElectricTruck.list_TruckTypes, obj_BatteryElectricTruck.prop_TruckType)
)
].TruckMode == obj_BatteryElectricTruck.List.list_TruckMode.DieselElectric,

		String.FromReal(Math.Round(obj_BatteryElectricTruck.var_DieselLevelPct, 1)) + "%",


		Math.If(

obj_BatteryElectricTruck.tbl_TruckTypes[
obj_BatteryElectricTruck.tbl_TruckTypes.TruckType.RowForKey(
String.FromList(obj_BatteryElectricTruck.list_TruckTypes, obj_BatteryElectricTruck.prop_TruckType)
)
].TruckMode == obj_BatteryElectricTruck.List.list_TruckMode.BatterySwap ||

 obj_BatteryElectricTruck.tbl_TruckTypes[
obj_BatteryElectricTruck.tbl_TruckTypes.TruckType.RowForKey(
String.FromList(obj_BatteryElectricTruck.list_TruckTypes,obj_BatteryElectricTruck.prop_TruckType)
)
].TruckMode == obj_BatteryElectricTruck.List.list_TruckMode.BatteryElectric,


			Math.If(

obj_BatteryElectricTruck.BatteryStation.Contents.NumberWaiting != 0,


				String.FromReal(Math.Round(obj_BatteryElectricTruck.BatteryStation.Contents.FirstItem.obj_Battery.var_BatterySOCPct, 1)) + "%",

"0%"

),


			""


		)


	),


	Math.If(


		prop_DynamicLabelText == List.list_DynamicLabelText.TruckSpeed,


		String.FromReal(Math.Round(obj_BatteryElectricTruck.Movement.Rate / 1000, 0)) + "km/h",


		""


	)


)
